import mongoose from 'mongoose';
import { config } from 'dotenv';
import { logger } from '../utils/logger';

// Load environment variables
config({ path: '.env.test' });

// Set test environment
process.env.NODE_ENV = 'test';
process.env.JWT_SECRET = 'test-secret-key';
process.env.MONGODB_TEST_URI = 'mongodb://localhost:27017/healthcare-test';
process.env.PORT = '3001';

// Increase timeout for all tests
jest.setTimeout(30000);

// Suppress console output during tests
const originalConsole = { ...console };
global.console = {
  ...console,
  log: jest.fn(),
  error: jest.fn(),
  warn: jest.fn(),
  info: jest.fn(),
  debug: jest.fn(),
};

// Global error handlers
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Don't exit the process in test environment
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  // Don't exit the process in test environment
});

// Global beforeAll hook
beforeAll(async () => {
  try {
    await mongoose.connect(process.env.MONGODB_TEST_URI || '');
    logger.info('Connected to test database');
  } catch (error) {
    logger.error('Failed to connect to test database:', error);
    throw error;
  }
});

// Global afterAll hook
afterAll(async () => {
  try {
    // Restore original console
    global.console = originalConsole;
    
    // Close database connection
    await mongoose.connection.close();
    logger.info('Closed test database connection');
  } catch (error) {
    logger.error('Error during test cleanup:', error);
    throw error;
  }
});

// Global beforeEach hook
beforeEach(async () => {
  // Clear all collections before each test
  const collections = mongoose.connection.collections;
  for (const key in collections) {
    await collections[key].deleteMany({});
  }
}); 